-- Esqueleto do schema public da producao (so estrutura: tabelas, colunas, PK/UNIQUE/FK).
-- Gerado em 2026-10-24 a partir do catalogo (pg_attribute/pg_constraint), sem nenhuma linha de dado.
-- Enums proprios viram text; vector vira bytea; generated columns e sequencias viram IDENTITY ou
-- expressao equivalente. Usado pelo e2e da 20261024_03 e pelo portao vivo de retencao.
CREATE SCHEMA IF NOT EXISTS auth;
CREATE TABLE IF NOT EXISTS auth.users (id uuid PRIMARY KEY, email text, created_at timestamptz NOT NULL DEFAULT now(), last_sign_in_at timestamptz);
CREATE OR REPLACE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('request.jwt.claim.sub', true), '')::uuid $$;

